        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Excuse my dust.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Salary is no object: I want only enough to keep body and soul apart.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Wherever she went, including here, it was against her better judgment.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "The House Beautiful is, for me, the play lousy.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Drink and dance and laugh and lie,\nLove, the reeling midnight through,\nFor tomorrow we shall die!\n(But, alas, we never do.)", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "I might repeat to myself, slowly and soothingly, a list of quotations beautiful from minds profound; if I can remember any of the damn things.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "I'm never going to accomplish anything; that's perfectly clear to me. I'm never going to be famous. My name will never be writ large on the roster of Those Who Do Things. I don't do anything. Not one single thing. I used to bite my nails, but I don't even do that any more.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "One more drink and I'd have been under the host.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "It takes me six months to do a story. I think it out and then write it sentence by sentence—no first draft. I can't write five words but that I change seven.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "There's a hell of a distance between wise-cracking and wit. Wit has truth in it; wise-cracking is simply calisthenics with words.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "It's not the tragedies that kill us; it's the messes.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "All those writers who write about their own childhood! Gentle God, if I wrote about mine you wouldn't sit in the same room with me.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "if you can get through the twilight, you'll live through the night.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Too fucking busy, and vice versa.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "It serves me right for putting all my eggs in one bastard.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "You can lead a horticulture, but you can't make her think.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "What fresh hell can this be?", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "If you have any young friends who aspire to become writers, the second greatest favor you can do them is to present them with copies of The Elements of Style. The first greatest, of course, is to shoot them now, while they're happy.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Scratch a lover, and find a foe.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "If I didn't care for fun and such,\nI'd probably amount to much.\nBut I shall stay the way I am,\nBecause I do not give a damn.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Oh, life is a glorious cycle of song,\nA medley of extemporanea,\nAnd love is a thing that can never go wrong,\nAnd I am Marie of Roumania.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Razors pain you,\nRivers are damp,\nAcids stain you,\nAnd drugs cause cramp.\nGuns aren't lawful,\nNooses give,\nGas smells awful.\nYou might as well live.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Men seldom make passes\nAt girls who wear glasses.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "By the time you swear you're his,\nShivering and sighing,\nAnd he vows his passion is\nInfinite, undying,\nLady, make a note of this —\nOne of you is lying.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Some men tear your heart in two,\nSome men flirt and flatter,\nSome men never look at you,\nAnd that clears up the matter.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "I am sister to the rain;\nFey and sudden and unholy,\nPetulant at the windowpane,\nQuickly lost, remembered slowly.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Four be the things I am wiser to know:\nIdleness, sorrow, a friend, and a foe.\nFour be the things I'd been better without:\nLove, curiosity, freckles, and doubt.\nThree be the things I shall never attain:\nEnvy, content, and sufficient champagne.\nThree be the things I shall have till I die:\nLaughter and hope and a sock in the eye.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Whose love is given over-well\nWill look on Helen's face in Hell;\nWhile they whose love is thin and wise\nMay view John Knox in Paradise.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "If with the literate I am\nImpelled to try an epigram,\nI never seek to take the credit;\nWe all assume that Oscar said it.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "They sicken of the calm, who knew the storm.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "It costs me never a stab nor squirm\nTo tread by chance upon a worm.\n\"Aha, my little dear,\" I say,\n\"Your clan will pay me back some day.\"", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "That woman speaks eighteen languages, and can't say No in any of them.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Brevity is the soul of lingerie.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Katharine Hepburn delivered a striking performance that ran the gamut of emotions, from A to B.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Sinbad is produced in accordance with the fine old Shubert precept that nothing succeeds like undress.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Anyone can do that—the stunt lies in not doing it.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "I thought that was going to be a good song, too, and then they went and rhymed “time” and “Rhine,” and spoiled everything.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "They exude an atmosphere of The New Republic—a sort of Crolier-than-thou air.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "There is one thing about Fiddlers Three, though, that held my attention all through the evening: Try as I might I could only discern two fiddlers.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "To quote the only line of Gertrude Stein's which I have ever been able to understand, \"It is wonderful how I am not interested.\"", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "You know how a play in dialect is. At the first act, you think, \"How quaint!\"; at the second act, you wish they would either stop using dialect or keep quiet; and at the third act, you wish you hadn't come. And Tillie, may I mention in passing, has four acts.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "If the English version is in what, in our youth, we used to speak of affectionately as dear old iambic pentameter, the actors mercifully abstain from reciting it that way; they speak their lines as good, hardy prose.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "The musical comedies of the month are She’s a Good Fellow and The Lady in Red, both of which owe their book and lyrics to Anne Caldwell—evidently a native of New York, judged by the casualness with which she rhymes “teacher” and “reach a.”", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "And you remember, Rabbi Wise has declared, in a heated moment, that our plays seem to be written for the hosiery buyers. If Dr. Wise had only witnessed our new summer reviews, he doubtless would have amended his statement to “read by the hosiery buyers.”", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "This use of soldiers to make a play popular seems too much like taking an unfair advantage of the uniform—hitting below the Sam Browne belt, as it were.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "In short, there is everything about this season's entertainment to make the Hippodrome what it always is—a Temple of the Arts to all those who hang pennants on their automobiles, use “Shake hands with my friend” as a formula for introduction, and sprinkle powdered sugar on their sliced tomatoes.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "The play holds the season's record, thus far, with a run of four evening performances and one matinée. By an odd coincidence, it ran just five performances too many.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Writing a book for the Follies seems to be about as profitable an occupation as furnishing flannel petticoats for the showgirls.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "The management's method of procedure is evidently to hire some well-known man to write the book, and then, as soon as it is written, to give it away to some deserving family, and go out and engage an assortment of specialty acts.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Van and Schenck put their songs over so skillfully that it isn't until their act is all done that you realize what extremely indifferent songs they are. Now, when John Steel is singing, on the other hand, you are never fooled for a moment.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Mr. Hodge plays with his accustomed ease, even carrying the thing so far as to repeat many of his lines with his eyes shut; and in a pretty spirit of reciprocity, many members of the audience sit through the play with their eyes shut.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Of course, there are many things to be said for the afternoon performance, chief among them being that it cuts in so generously on one's work.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Naturally, you know how you would feel on setting out to see a performance of Aucassin and Nicolette done by a company of little ones; you would strive to hurl yourself beneath the wheels of a friendly truck, on your way to the theatre.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Bringing in a wounded soldier is getting to be rather like waving an American flag at the end of an act. One cannot harbor feelings of unmixed admiration for the playwright who will hide behind either of them.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "So seeing that there is nothing further to say, I shall go right on talking about The Circle, thus proving that I am a born reviewer of plays.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Rockliffe Fellowes gives a likable performance of the secondary crook's rôle, and there are some decidedly agreeable-looking doughnuts consumed in the first act. And that is about all one can say for Pot Luck.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "If you arrive late, you won't know what anything is about, and if you are there all the way from the beginning, you won't care.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "There is one thing that appreciably eases the strain for the plays that arrive at this time of year, and that is that practically nothing is expected of them.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "The murdered man meets his death in an intriguing and novel manner, which the management asks its customers, as a personal favor, not to reveal to possible future audiences. It remains a secret, chummily shared by those that have seen the play and the four or five million who read it in its original form as a Saturday Evening Post story a year or so ago.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "It is advertised as “a seagoin’ comedy,” and anytime they go leaving off the final g that way, you know what to expect.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Two things made The Dice of the Gods, another play about drugs, seem much better than it had any real right to seem. One was that Morphia had come first, and once you had seen Morphia, nothing seemd so very terrible to you.", Author = "Dorothy Parker" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Dorothy_Parker", Text = "Get me a new husband", Author = "Dorothy Parker" },
        };
    }
}